<?php
namespace App\Services; use CodeIgniter\HTTP\Files\UploadedFile; use DomainException; use finfo; use Throwable;
final class VerificationAssistanceService { public function submit(array $input,?UploadedFile $file):array{$data=$this->validate($input,$file);$c=config('VerificationAssistance');if($c->apiKey===''||$c->baseUrl==='')throw new DomainException('Verification Assistance is temporarily unavailable. Please try again later.');try{$ch=curl_init($c->baseUrl.'/api/verification-assistance');$post=$data+['supporting_document'=>new \CURLFile($file->getTempName(),$data['_mime'],$file->getClientName())];unset($post['_mime']);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_HTTPHEADER=>['X-Verification-Assistance-Key: '.$c->apiKey,'Accept: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_CONNECTTIMEOUT=>3]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_error($ch);curl_close($ch);if($body===false||$status===0)throw new \RuntimeException($error?:'connection failure');$json=json_decode($body,true);if($status===201&&is_array($json)&&($json['received']??false)===true)return ['received'=>true];$message=is_array($json)?($json['messages']['error']??$json['message']??''):'';if(is_string($message)&&str_contains($message,'active assistance request'))throw new DomainException('An active verification assistance request already exists.');throw new DomainException('Verification Assistance could not accept the request. Please try again later.');}catch(DomainException $e){throw $e;}catch(Throwable $e){log_message('error','Verification assistance request failed ({exceptionClass}).',['exceptionClass'=>$e::class]);throw new DomainException('Verification Assistance is temporarily unavailable. Please try again later.');}}private function validate(array $p,?UploadedFile $f):array{$v=static fn($k,$m)=>is_string($p[$k]??null)?trim(mb_substr($p[$k],0,$m)):'';$d=['student_id'=>$v('student_id',30),'full_name'=>$v('full_name',150),'contact_email'=>strtolower($v('contact_email',150)),'program'=>$v('program',150),'explanation'=>$v('explanation',2000)];if(preg_match('/\A[A-Za-z0-9-]{1,30}\z/',$d['student_id'])!==1||$d['full_name']===''||filter_var($d['contact_email'],FILTER_VALIDATE_EMAIL)===false||$d['program']===''||$d['explanation']==='')throw new DomainException('Complete all required fields with valid values.');$c=config('VerificationAssistance');if(!$f||$f->hasMoved()||!$f->isValid()||$f->getError()!==UPLOAD_ERR_OK||$f->getSize()<1||$f->getSize()>$c->maxFileSizeBytes)throw new DomainException('Upload a complete PDF, JPG, or PNG document under 5 MiB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f->getTempName());$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext||!in_array(strtolower(pathinfo($f->getClientName(),PATHINFO_EXTENSION)),[$ext,$ext==='jpg'?'jpeg':$ext],true))throw new DomainException('Upload a valid PDF, JPG, or PNG document.');return $d+['_mime'=>$mime];}}
